async (page) => {
  const urls = ['http://127.0.0.1:9101/people','http://127.0.0.1:9101/staff','http://127.0.0.1:9102/spa','http://127.0.0.1:9103/Residents.aspx','http://127.0.0.1:9104/Residents.aspx'];
  const ctx = page.context();
  const out = await Promise.all(urls.map(async u => {
    const p = await ctx.newPage();
    try {
      await p.goto(u, {waitUntil:'networkidle', timeout:20000});
      await p.waitForTimeout(800);
      const info = await p.evaluate(() => {
        const tables = [...document.querySelectorAll('table')].map(t => ({id:t.id, cls:t.className, rows:t.rows.length, head:[...t.rows].slice(0,3).map(r=>r.innerText.replace(/\s+/g,' ').slice(0,200)), tail:[...t.rows].slice(-3).map(r=>r.innerText.replace(/\s+/g,' ').slice(0,200))}));
        const links = [...document.querySelectorAll('a,button')].map(a=>(a.innerText||a.value||'').trim()+' -> '+(a.getAttribute('href')||'')).filter(s=>s.length>4).slice(0,60);
        return {title:document.title, tables, text: document.body.innerText.slice(0,1500), links};
      });
      return {u, ...info};
    } catch(e) { return {u, err:String(e)}; } finally { await p.close(); }
  }));
  return JSON.stringify(out, null, 1);
}

