  const rowsOf = (p, sel) => p.evaluate((sel) => {
    const t = document.querySelector(sel);
    return [...t.rows].filter(r => r.offsetParent !== null && r.querySelector('a[href*="Delete"]') && getComputedStyle(r).display!=='none' && getComputedStyle(r).visibility!=='hidden')
      .map(r => [...r.cells].map(c=>c.innerText.trim()).join(' | '));
  }, sel);
  const aspx = async (u, sel, tgt) => {
    const p = await ctx.newPage();
    await p.goto(u, {waitUntil:'networkidle'});
    const firstHtml = await p.evaluate((sel)=>{const t=document.querySelector(sel); return t.outerHTML.slice(0,2500)+'\nHIDDEN:'+[...document.querySelectorAll('input[type=hidden]')].map(i=>i.name+'='+i.value.slice(0,80)).join(';');}, sel);
    const all = []; let n = 1;
    while (true) {
      const r = await rowsOf(p, sel); all.push(...r.map(x=>`p${n}: `+x));
      const next = await p.$(`a[href*="'Page$${n+1}'"]`);
      if (!next || n > 60) break;
      await Promise.all([p.waitForLoadState('networkidle'), next.click()]);
      await p.waitForTimeout(300); n++;
    }
    await p.close();
    return {u, pages:n, count: all.length, all, firstHtml};
  };
  const staff = async () => {
    const p = await ctx.newPage(); const all = []; let n=1;
    await p.goto('http://127.0.0.1:9101/staff', {waitUntil:'networkidle'});
    const firstHtml = await p.evaluate(()=>document.querySelector('table').outerHTML.slice(0,1500));
    while (true) {
      const r = await p.evaluate(()=>[...document.querySelectorAll('table tr')].filter(r=>r.querySelector('td') && r.offsetParent!==null).map(r=>[...r.cells].map(c=>c.innerText.trim()).join(' | ')));
      all.push(...r.map(x=>`p${n}: `+x));
      const next = await p.$('a:has-text("Next")'); if (!next || n>60) break;
      await Promise.all([p.waitForLoadState('networkidle'), next.click()]); n++;
    }
    await p.close(); return {u:'staff', pages:n, count:all.length, all, firstHtml};
  };
  const spa = async () => {
    const p = await ctx.newPage(); const all=[]; let n=1;
    await p.goto('http://127.0.0.1:9102/spa', {waitUntil:'networkidle'}); await p.waitForTimeout(500);
    const firstHtml = await p.evaluate(()=>document.body.innerHTML.slice(0,3000));
    while (true) {
      const txt = await p.evaluate(()=>document.body.innerText);
      all.push(`p${n}: `+txt.replace(/\n/g,' / '));
      const m = txt.match(/Page (\d+) of (\d+)/); if (!m || +m[1] >= +m[2] || n>30) break;
      await p.click('text=›'); await p.waitForTimeout(600); n++;
    }
    await p.close(); return {u:'spa', pages:n, all, firstHtml};
  };
  const res = await Promise.all([staff(), spa(), aspx('http://127.0.0.1:9103/Residents.aspx','#ctl00_gv'), aspx('http://127.0.0.1:9104/Residents.aspx','#gv')]);
  return JSON.stringify(res, null, 1);
}

